pub fn is_prime(n: i8) -> bool {
    // By definition, primes are integers >= 2.
    if n < 2 {
        return false;
    }

    // Try every possible divisor k in [2, n-1].
    let mut k: i8 = 2;
    while k < n {
        // If k divides n evenly, n is not prime.
        if n % k == 0 {
            return false;
        }
        k += 1;
    }

    // No divisor found ⇒ n is prime.
    true
}

